std::mutex mtx1, mtx2;

auto t_job1 = [] {
    mtx1.lock();
    // T1 holds mtx1
    mtx2.lock(); // T1 waits for T2
    // ... Critical section ...
    mtx2.unlock();
    mtx1.unlock();
};

auto t_job2 = [] {
    mtx2.lock();
    // T2 holds mtx2
    mtx1.lock(); // T2 waits for T1
    // ... Critical section ...
    mtx1.unlock();
    mtx2.unlock();
};

std::thread t1(t_job1);
std::thread t2(t_job2);

// t1.join(); // Indefinite stall (Deadlock)
// Condition: Circular wait (1->2, 2->1) + Mutual Exclusion.
